parameters.jsCode:
const raw = $input.first().json.output || '';

// Extract [[LEAD:{...}]] marker if present
const leadMatch = raw.match(/\[\[LEAD:(\{.*?\})\]\]/s);
let leadData = null;
if (leadMatch) {
  try { leadData = JSON.parse(leadMatch[1]); } catch(e) { leadData = null; }
}

// Extract [[QUOTE_RESPONSE:{...}]] marker if present
const quoteMatch = raw.match(/\[\[QUOTE_RESPONSE:(\{.*?\})\]\]/s);
let quoteResponse = null;
if (quoteMatch) {
  try { quoteResponse = JSON.parse(quoteMatch[1]); } catch(e) { quoteResponse = null; }
}

// Strip both markers from message sent to customer
const cleanMessage = raw
  .replace(/\n?\[\[LEAD:\{.*?\}\]\]/s, '')
  .replace(/\n?\[\[QUOTE_RESPONSE:\{.*?\}\]\]/s, '')
  .trim();

return [{
  json: {
    agentReply: quoteResponse ? '' : cleanMessage,
    leadData: leadData,
    hasLead: leadData !== null,
    quoteResponse: quoteResponse,
    hasQuoteResponse: quoteResponse !== null,
    waId: $('Normalize Input').first().json.from
  }
}];

const resp = $input.first().json;
const from = $('Normalize Input').first().json.from;

return [{
  json: {
    reply: resp.reply || 'Thank you for your response.',
    accepted: resp.accepted === true,
    from: from,
    otherPlumbers: resp.otherPlumbers || []
  }
}];

const otherPlumbers = $('Parse Plumber Response').first().json.otherPlumbers || [];
if (otherPlumbers.length === 0) return [];
return otherPlumbers.map(p => ({
  json: {
    waId: p.waId,
    rejectionMessage: p.rejectionMessage || 'This job has been assigned to another plumber. Thanks for responding — we will send you the next available job!'
  }
}));

// Get customer message from correct source
// Audio path: Normalize Input text is empty, transcript is in Use Transcript
// Text path: Normalize Input text has the message
const messageType = $('Normalize Input').item.json.messageType || 'text';
const normalizeText = $('Normalize Input').item.json.text || '';

let customerMessage = normalizeText;

if (messageType === 'audio' || !normalizeText) {
  try {
    const transcript = $('Use Transcript').item.json.text || '';
    if (transcript) customerMessage = transcript;
  } catch(e) {
    // Use Transcript didn't run (text message path) — keep normalizeText
  }
}

return [{
  json: {
    ...$input.first().json,
    customerMessage: customerMessage
  }
}];
